// Bundles summary-rules.txt (and the README review notes) into TypeScript so the
// deployed server code doesn't depend on data files existing at runtime.
import { readFileSync, writeFileSync } from "node:fs";

const rules = readFileSync("soundsense-exercise-data/summary-rules.txt", "utf8");
const out =
  "// GENERATED by scripts/gen-rules.mjs from soundsense-exercise-data/summary-rules.txt. Do not edit.\n" +
  `export const SUMMARY_RULES = ${JSON.stringify(rules)};\n`;
writeFileSync("src/lib/rules.generated.ts", out);
